/*selectBuyerGrAmt*/
SELECT NVL(SUM(ITEM_AMT), 0) FROM ICOMGRDT WHERE 1=1 AND GR_DATE BETWEEN SUBSTR(#{issue_date}, 0, 6) || '01' AND #{issue_date} AND AR_BILL_FLAG = 'N' AND STATUS <> 'D'
AND BUYER IN ('KRDOOD0001' ,'KRDOOS0004')
AND BUYER = #{buyer_code}

