/*updateMasterCmClSalesTaxsheetCreation_ICOMGRDT*/

		UPDATE 
		    ICOMGRDT GR /* 구매사별 입고정보 */
		SET
		    AR_CLOSE_DEPT       = LPAD(#{KEP_DEPT_CODE},3,0)
		  , AR_CLOSE_MONTH      = #{YM_date}
		  , AR_CLOSE_REVISION   = #{close_revision}
		  , AR_BILL_FLAG        = 'Y'
		  , AR_TAX_BILL_NO      = 'PARTIAL'
		WHERE 1=1
		AND GR.STATUS <> 'D'



		AND (GR.BUYER = 'KRDOOD0001' OR GR.BUYER = 'KRDOOS0004' )


		AND (GR.BUYER = 'KRISUC0004' OR GR.BUYER = 'KRISUC0005' OR GR.BUYER = 'KRISUC0006')


		AND (GR.BUYER = 'KRCOWA0001' OR GR.BUYER = 'KRCOWA0005' OR GR.BUYER = 'KRCOWA0006')


		AND GR.BUYER = #{BUYER}





		AND GR.GR_DATE BETWEEN #{YM_date} || '01' AND #{issue_date}


		AND GR.GR_DATE BETWEEN #{YM_date} || '11' AND #{issue_date}


		AND GR.GR_DATE BETWEEN #{YM_date} || '21' AND #{issue_date}





		AND GR.GR_DATE BETWEEN #{YM_date} || '01' AND #{YM_date} || '15'


		AND GR.GR_DATE BETWEEN #{YM_date} || '16' AND #{YM_date} || '31'
